Let $X_{\ell}$, $Y_{\ell}$, $X_{r}$, and $Y_{r}$ be sets satisfying the following properties:  egin{itemize} \item $X_{\ell} \cap X_{r} = \{x_{2}, x_{1}, x_{0}\}$ for some distinct $x_{0}$, $x_{1}$, and $x_{2}$; \item $Y_{\ell} \cap Y_{r} = \{y_{0}, y_{1}, y_{2}\}$ for some distinct $y_{0}$, $y_{1}$, and $y_{2}$; \item $X_{\ell}$ is disjoint with $Y_{r}$; and \item $Y_{\ell}$ is disjoint with $X_{r}$. \end{itemize} Let $B_{\ell} \in \mathbb{Z}_{2}^{X_{\ell} 	imes Y_{\ell}}$ and $B_{r} \in \mathbb{Z}_{2}^{X_{r} 	imes Y_{r}}$ be matrices of the form  egin{center} 
oindent  egin{tikzpicture}  egin{scope}[scale=0.5, shift={(-5.5, -3)}] 
ode[anchor=east] at (0, 3) {$B_{\ell} =$}; \draw (0, 0) -- (5, 0) -- (5, 6) -- (0, 6) -- cycle; \draw (0, 2) -- (5, 2); \draw (4, 0) -- (4, 6); \draw (2, 0) -- (2, 3) -- (5, 3); \draw (4, 1) -- (5, 1); \draw (3, 2) -- (3, 3); 
ode at (2, 4) {$A_{\ell}$}; 
ode at (1, 1) {$D_{\ell}$}; 
ode at (4.5, 4) {$0$}; 
ode at (2.5, 2.5) {$1$}; 
ode at (3.5, 2.5) {$1$}; 
ode at (4.5, 2.5) {$0$}; 
ode at (4.5, 1.5) {$1$}; 
ode at (4.5, 0.5) {$1$}; 
ode at (3, 1) {$D_{0}$}; \end{scope} 
ode[anchor=west] at (0, 0) {and};  egin{scope}[scale=0.5, shift={(3.5, -2.5)}] 
ode[anchor=east] at (0, 2.5) {$B_{r} =$}; \draw (0, 0) -- (6, 0) -- (6, 5) -- (0, 5) -- cycle; \draw (2, 0) -- (2, 5); \draw (0, 4) -- (6, 4); \draw (0, 2) -- (3, 2) -- (3, 5); \draw (1, 4) -- (1, 5); \draw (2, 3) -- (3, 3); 
ode at (1, 1) {$D_{r}$}; 
ode at (1, 3) {$D_{0}$}; 
ode at (0.5, 4.5) {$1$}; 
ode at (1.5, 4.5) {$1$}; 
ode at (4, 4.5) {$0$}; 
ode at (2.5, 2.5) {$1$}; 
ode at (2.5, 3.5) {$1$}; 
ode at (2.5, 4.5) {$0$}; 
ode at (4, 2) {$A_{r}$}; \end{scope} \end{tikzpicture} \end{center} where $D_{0}$ is invertible. Then the $3$-sum $B = B_{\ell} \oplus_{3} B_{r}$ of $B_{\ell}$ and $B_{r}$ is defined as  egin{center} 
oindent  egin{tikzpicture}  egin{scope}[scale=0.5, shift={(0, -4)}] 
ode[anchor=east] at (0, 4) {$B =$}; \draw (0, 0) -- (8, 0) -- (8, 8) -- (0, 8) -- cycle; \draw (0, 4) -- (8, 4); \draw (4, 0) -- (4, 8); \draw (0, 2) -- (5, 2) -- (5, 5) -- (2, 5) -- (2, 0); \draw (3, 4) -- (3, 5); \draw (4, 3) -- (5, 3); 
ode at (2, 6) {$A_{\ell}$}; 
ode at (6, 2) {$A_{r}$}; 
ode at (6, 6) {$0$}; 
ode at (1, 1) {$D_{\ell r}$}; 
ode at (1, 3) {$D_{\ell}$}; 
ode at (3, 1) {$D_{r}$}; 
ode at (3, 3) {$D_{0}$}; 
ode at (2.5, 4.5) {$1$}; 
ode at (3.5, 4.5) {$1$}; 
ode at (4.5, 4.5) {$0$}; 
ode at (4.5, 3.5) {$1$}; 
ode at (4.5, 2.5) {$1$}; \end{scope} 
ode[anchor=west] at (4.25, 0) {where $D_{\ell r} = D_{r} \cdot (D_{0})^{-1} \cdot D_{\ell}$.}; \end{tikzpicture} \end{center} Here the indexing is consistent between all the matrices, $D_{0} \in \mathbb{Z}_{2}^{\{x_{1}, x_{0}\} 	imes \{y_{0}, y_{1}\}}$, and the submatrix  egin{tikzpicture}  egin{scope}[scale=0.5, shift={(-3.5, -1.5)}] \draw (0, 0) -- (3, 0) -- (3, 3) -- (0, 3) -- cycle; \draw (0, 2) -- (3, 2); \draw (2, 0) -- (2, 3); \draw (1, 2) -- (1, 3); \draw (2, 1) -- (3, 1); 
ode at (1, 1) {$D_{0}$}; 
ode at (0.5, 2.5) {$1$}; 
ode at (1.5, 2.5) {$1$}; 
ode at (2.5, 2.5) {$0$}; 
ode at (2.5, 1.5) {$1$}; 
ode at (2.5, 0.5) {$1$}; \end{scope} \end{tikzpicture} is indexed by $\{x_{2}, x_{1}, x_{0}\} 	imes \{y_{0}, y_{1}, y_{2}\}$ in $B_{\ell}$, $B_{r}$, and $B$.

We call $D_{0}' \in \mathbb{Q}^{\{x_{1}, x_{0}\} 	imes \{y_{0}, y_{1}\}}$ the canonical signing of $D_{0} \in \mathbb{Z}_{2}^{\{x_{1}, x_{0}\} 	imes \{y_{0}, y_{1}\}}$ if \[ D_{0} =  egin{bmatrix} 1 & 0 \ 0 & 1 \ \end{bmatrix} \quad 	ext{and} \quad D_{0}' =  egin{bmatrix} 1 & 0 \ 0 & -1 \end{bmatrix}, \quad 	ext{or} \quad D_{0} =  egin{bmatrix} 1 & 1 \ 0 & 1 \end{bmatrix} \quad 	ext{and} \quad D_{0}' =  egin{bmatrix} 1 & 1 \ 0 & 1 \end{bmatrix}. \] Similarly, we call $S' \in \mathbb{Q}^{\{x_{2}, x_{1}, x_{0}\} 	imes \{y_{0}, y_{1}, y_{2}\}}$ the canonical signing of $S \in \mathbb{Z}_{2}^{\{x_{2}, x_{1}, x_{0}\} 	imes \{y_{0}, y_{1}, y_{2}\}}$ if  egin{center} 
oindent  egin{tikzpicture}  egin{scope}[scale=0.5, shift={(-3.5, -1.5)}] 
ode[anchor=east] at (0, 1.5) {$S =$}; \draw (0, 0) -- (3, 0) -- (3, 3) -- (0, 3) -- cycle; \draw (0, 2) -- (3, 2); \draw (2, 0) -- (2, 3); \draw (1, 2) -- (1, 3); \draw (2, 1) -- (3, 1); 
ode at (1, 1) {$D_{0}$}; 
ode at (0.5, 2.5) {$1$}; 
ode at (1.5, 2.5) {$1$}; 
ode at (2.5, 2.5) {$0$}; 
ode at (2.5, 1.5) {$1$}; 
ode at (2.5, 0.5) {$1$}; \end{scope} 
ode[anchor=west] at (0, 0) {and};  egin{scope}[scale=0.5, shift={(3.5, -1.5)}] 
ode[anchor=east] at (0, 1.5) {$S' =$}; \draw (0, 0) -- (3, 0) -- (3, 3) -- (0, 3) -- cycle; \draw (0, 2) -- (3, 2); \draw (2, 0) -- (2, 3); \draw (1, 2) -- (1, 3); \draw (2, 1) -- (3, 1); 
ode at (1, 1) {$D_{0}'$}; 
ode at (0.5, 2.5) {$1$}; 
ode at (1.5, 2.5) {$1$}; 
ode at (2.5, 2.5) {$0$}; 
ode at (2.5, 1.5) {$1$}; 
ode at (2.5, 0.5) {$1$}; \end{scope} \end{tikzpicture} \end{center} To simplify notation, going forward we use $D_{0}$, $D_{0}'$, $S$, and $S'$ to refer to the matrices of the form above. Observe that the canonical signing $S'$ of $S$ (from Definition~ef{matrix3x3signed}) is TU.

Suppose that $B_{\ell}$ and $B_{r}$ from Definition~ef{standardReprSum3} have TU signings $B_{\ell}'$ and $B_{r}'$, respectively. Let $B_{\ell}''$ and $B_{r}''$ be the canonical re-signings (from Definition~ef{Matrix.toCanonicalSigning}) of $B_{\ell}'$ and $B_{r}'$, respectively. Let $A_{\ell}''$, $A_{r}''$, $D_{\ell}''$, $D_{r}''$, and $D_{0}''$ be blocks of $B_{\ell}''$ and $B_{r}''$ analogous to blocks $A_{\ell}$, $A_{r}$, $D_{\ell}$, $D_{r}$, and $D_{0}$ of $B_{\ell}$ and $B_{r}$. The canonical signing $B''$ of $B$ is defined as  egin{center} 
oindent  egin{tikzpicture}  egin{scope}[scale=0.5, shift={(0, -4)}] 
ode[anchor=east] at (0, 4) {$B'' =$}; \draw (0, 0) -- (8, 0) -- (8, 8) -- (0, 8) -- cycle; \draw (0, 4) -- (8, 4); \draw (4, 0) -- (4, 8); \draw (0, 2) -- (5, 2) -- (5, 5) -- (2, 5) -- (2, 0); \draw (3, 4) -- (3, 5); \draw (4, 3) -- (5, 3); 
ode at (2, 6) {$A_{\ell}''$}; 
ode at (6, 2) {$A_{r}''$}; 
ode at (6, 6) {$0$}; 
ode at (1, 1) {$D_{\ell r}''$}; 
ode at (1, 3) {$D_{\ell}''$}; 
ode at (3, 1) {$D_{r}''$}; 
ode at (3, 3) {$D_{0}''$}; 
ode at (2.5, 4.5) {$1$}; 
ode at (3.5, 4.5) {$1$}; 
ode at (4.5, 4.5) {$0$}; 
ode at (4.5, 3.5) {$1$}; 
ode at (4.5, 2.5) {$1$}; \end{scope} 
ode[anchor=west] at (4.25, 0) {where $D_{\ell r}'' = D_{r}'' \cdot (D_{0}'')^{-1} \cdot D_{\ell}''$.}; \end{tikzpicture} \end{center} Note that $D_{0}''$ is non-singular by construction, so $D_{\ell r}''$ and hence $B''$ are well-defined.
